(() => {
  const K = 'sofa-so-good:save:';
  const r7 = window.__r7 = {
    raw: (slot = 'autosave') => localStorage.getItem(K + slot),
    plansRaw: () => localStorage.getItem('sofa.floorplans.v1'),
    fp(slot = 'autosave') {
      const r = localStorage.getItem(K + slot); if (!r) return null;
      const j = JSON.parse(r); const items = j.items || [];
      const s = JSON.stringify(items.map((i) => [i.id, i.defId, i.position, i.rotation, i.props]));
      let h = 0; for (let k = 0; k < s.length; k++) h = (h * 31 + s.charCodeAt(k)) | 0;
      return { n: items.length, h, note: j.note ?? '' };
    },
    index() { try { return JSON.parse(localStorage.getItem('sofa-so-good:save-index') || '[]') } catch { return [] } },
    backups() { return this.index().filter((e) => e.slot.startsWith('before-shared-link-')).map((e) => e.slot) },
    named() { return this.index().filter((e) => !e.slot.startsWith('before-shared-link-')).map((e) => e.slot) },
    get(k) { const v = localStorage.getItem('r7y:' + k); return v == null ? null : JSON.parse(v) },
    set(k, v) { localStorage.setItem('r7y:' + k, JSON.stringify(v)) },
    eq(a, b) { return JSON.stringify(a) === JSON.stringify(b) },
    must(c, msg) { if (!c) throw new Error(msg) },
    log(tag, o) { console.log('[r7y] ' + tag + ' ' + JSON.stringify(o)); try { const j = JSON.parse(localStorage.getItem('r7y:journal') || '[]'); j.push([new Date().toISOString().slice(11, 19), tag, o]); localStorage.setItem('r7y:journal', JSON.stringify(j)) } catch {} },
    toasts: [],
    toast(t) { return this.toasts.find((x) => (x.title + ' ' + x.message).includes(t)) },
    clearToasts() { window.__store.setState({ notifications: [] }) },
    st: () => window.__store.getState(),
  };
  const seen = new Set();
  const rec = (st) => { for (const n of st.notifications || []) if (!seen.has(n.id)) { seen.add(n.id); r7.toasts.push({ title: n.title, message: n.message ?? '', action: n.actionLabel ?? null, kind: n.kind }) } };
  // Pin toasts open (autoDismissMs:null) so the screenshots can see them; the
  // recorder above is the evidence, the pin is only for the pictures.
  const pin = (st) => { if ((st.notifications || []).some((n) => n.autoDismissMs != null && n.kind !== 'progress')) window.__store.setState({ notifications: st.notifications.map((n) => (n.kind === 'progress' ? n : { ...n, autoDismissMs: null })) }) };
  rec(window.__store.getState()); pin(window.__store.getState());
  window.__store.subscribe((st) => { rec(st); pin(st) });
})()

(async () => {
  const r7 = window.__r7; const st = r7.st;
  const { snapToNearestWindow, windowFixtureProps } = await import('/src/furniture/placement/windowSnap.ts');
  const li = await import('/src/furniture/lightInteract.ts');
  const s = st();
  const lamp = s.items.find((i) => i.defId === 'table-lamp');
  const ceil = s.items.find((i) => i.defId === 'ceiling-light');
  r7.must(lamp && ceil && li.nextLightPowerProps(lamp.defId, lamp.props), 'default flat has no table-lamp/ceiling-light');
  s.setItems([lamp, ceil]);
  const plan = st().floorPlan; const op = plan.openings.find((o) => o.kind === 'window');
  const w = plan.walls.find((x) => x.id === op.wallId);
  const len = Math.hypot(w.end[0] - w.start[0], w.end[1] - w.start[1]);
  const t = op.offset + op.width / 2;
  const p = [w.start[0] + ((w.end[0] - w.start[0]) / len) * t, w.start[1] + ((w.end[1] - w.start[1]) / len) * t];
  const snap = snapToNearestWindow(plan.walls, plan.openings, p);
  r7.must(snap, 'no window to hang the curtain on');
  st().addItem({ defId: 'curtains', position: snap.position, rotation: snap.rotation, props: { ...windowFixtureProps('curtains', snap.window, plan.ceilingHeight), draw: 0 } });
  st().setDesignNote('SENDER NOTE: small 3-item design');
  await new Promise((r) => setTimeout(r, 300));
  r7.must(st().items.length === 3, 'sender design is not 3 items: ' + st().items.length);
  const showroom = window.__shareHash(true);
  const design = window.__shareHash(false);
  r7.must(showroom.startsWith('#/showroom/') && design.startsWith('#/design/'), 'bad minted routes');
  // S4 fixtures: the valid code with its middle overwritten.
  const code = showroom.slice('#/showroom/'.length); const mid = code.length >> 1;
  const bad = code.slice(0, mid) + 'Zq9Zq9Zq9Zq9Zq9Zq9' + code.slice(mid + 18);
  // S2 fixture: a real payload with 2001 items, encoded without the size budget.
  const ds = await import('/src/features/designShare.ts');
  const ps = await import('/src/features/planShare.ts');
  const payload = ds.buildDesignSharePayload(st(), true);
  payload.items = Array.from({ length: ps.MAX_SHARED_ITEMS + 1 }, (_, i) => ({ ...payload.items[0], id: 'r7y-bulk-' + i }));
  const over = '#/showroom/' + ps.encodePlan(payload);
  r7.set('showroom', showroom); r7.set('design', design);
  r7.set('corruptShowroom', '#/showroom/' + bad); r7.set('corruptDesign', '#/design/' + bad);
  r7.set('over', over); r7.set('sender', { n: 3, note: 'SENDER NOTE: small 3-item design' });
  r7.log('minted', { showroom: showroom.length, design: design.length, over: over.length, overItems: payload.items.length });
})()

(async () => {
  const r7 = window.__r7; const st = r7.st;
  window.__loadTemplate('tpl-hdb-maisonette');
  await new Promise((r) => setTimeout(r, 500));
  const { furnishPlanItems } = await import('/src/furniture/furnishPlan.ts');
  const { LAYOUT_PRESETS } = await import('/src/furniture/layoutPresets.ts');
  const { BUILTIN_CATALOG } = await import('/src/furniture/builtinCatalog.ts');
  let best = null;
  for (const p of LAYOUT_PRESETS) { const items = furnishPlanItems(st().floorPlan, p, BUILTIN_CATALOG, st().doors); if (!best || items.length > best.items.length) best = { id: p.id, items } }
  st().setItems(best.items);
  await new Promise((r) => setTimeout(r, 300));
  const heavy = window.__shareHash(true);
  const unknown = st().items.filter((i) => !BUILTIN_CATALOG[i.defId]).map((i) => i.defId);
  r7.set('heavy', heavy); r7.set('heavyN', st().items.length); r7.set('heavyUnknown', unknown.length);
  r7.log('heavy', { preset: best.id, n: st().items.length, chars: heavy.length, notInBuiltinCatalog: unknown });
})()

