(() => {
  const r7 = window.__r7; const st = r7.st;
  const s = st(); r7.must(s.items.length === 87 && !s.viewOnly, 'visitor did not boot on the default 87-item flat: ' + s.items.length);
  const victims = s.items.filter((i) => !/light|lamp|sconce|fan/.test(i.defId)).slice(0, 5);
  for (const v of victims) st().deleteItem(v.id, { silent: true });
  const sofa = st().items.find((i) => /sofa/.test(i.defId)) || st().items[0];
  st().moveItem(sofa.id, [sofa.position[0] + 0.35, sofa.position[1] - 0.2]);
  st().setDesignNote('VISITOR NOTE: my own flat');
  r7.set('marker', sofa.id);
  r7.log('distinctive', { deleted: victims.map((v) => v.defId), moved: sofa.defId, n: st().items.length });
})()

