(async () => {
  const r7 = window.__r7; const st = r7.st;
  const li = await import('/src/furniture/lightInteract.ts');
  const wf = await import('/src/furniture/windowFixtureInteract.ts');
  const { BUILTIN_CATALOG } = await import('/src/furniture/builtinCatalog.ts');
  const s0 = st();
  r7.must(s0.viewOnly === true, '1: not in a showroom session');
  const light = s0.items.find((it) => li.nextLightPowerProps(it.defId, it.props));
  const fix = s0.items.find((it) => BUILTIN_CATALOG[it.defId] && wf.isInteractableWindowFixture(BUILTIN_CATALOG[it.defId]));
  r7.must(light && fix, '1: showroom design lacks a switchable light or a curtain');
  const snap = (s) => ({ hour: s.manualHour, mode: s.timeMode, weather: s.weather, lights: s.lightsMode, mood: s.lightMood, cam: s.cameraMode, note: s.designNote, light: s.items.find((i) => i.id === light.id).props.lightOn ?? null, curtain: JSON.stringify(s.items.find((i) => i.id === fix.id).props) });
  const before = snap(s0);
  st().setTimeMode('manual'); st().setManualHour(19.5);
  st().setWeather('rain');
  st().setLightsMode('off'); st().setLightMood('movie');
  st().toggleLightPower(light.id);
  st().toggleWindowFixture(fix.id);
  st().setCameraMode('firstPerson');
  st().setDesignNote('typed by the visitor inside the showroom');
  await new Promise((r) => setTimeout(r, 400));
  const after = snap(st());
  r7.log('1 interactions', { before, after });
  for (const k of ['hour', 'weather', 'lights', 'mood', 'cam', 'note', 'light', 'curtain']) r7.must(before[k] !== after[k], '1: interaction on ' + k + ' did not take effect');
  // Also fire the page-lifecycle flush the autosave listens to.
  window.dispatchEvent(new Event('pagehide'));
})()

